*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#050a12;color:#e8f1f3;font-family:'Space Grotesk',sans-serif}button{font:inherit;color:inherit}#game{position:relative;width:100%;height:100%;overflow:hidden;background:#050a12;isolation:isolate}#scene{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at center,transparent 30%,rgba(2,7,13,.22) 70%,rgba(2,7,13,.74) 140%);z-index:1}.scanline{position:absolute;inset:0;pointer-events:none;z-index:8;opacity:.1;background:repeating-linear-gradient(0deg,transparent 0px,transparent 3px,rgba(161,219,229,.07) 4px)}.topbar{position:absolute;left:0;right:0;top:0;padding:24px 34px;display:flex;align-items:center;justify-content:space-between;z-index:3}.brand{display:flex;align-items:center;gap:9px;font-weight:700;letter-spacing:.18em;font-size:12px}.brand-mark{font-size:23px;color:#8ce5e4}.brand small{margin-left:7px;padding-left:13px;border-left:1px solid #ffffff24;color:#91a5ad;font:10px 'DM Mono',monospace;letter-spacing:.09em}.mission-tag{position:absolute;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:9px;font:10px 'DM Mono',monospace;letter-spacing:.11em;color:#9eb4bb}.mission-tag b{font-weight:400;color:#eff7f5;margin-left:10px}.live-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:#82e8d2;box-shadow:0 0 10px #82e8d2}.icon-btn{width:34px;height:34px;border:1px solid #ffffff24;background:#07121d88;border-radius:50%;font-size:16px;cursor:pointer;color:#a8c0c5}.hud-left{position:absolute;z-index:3;top:104px;left:34px;width:175px}.readout{margin-bottom:20px}.readout>span,.coordinates>span,.velocity>span,.tether>span{display:block;color:#9fb0b4;font:9px 'DM Mono',monospace;letter-spacing:.13em}.readout strong{display:block;font:25px 'DM Mono',monospace;line-height:1.55;color:#e7f2ef}.readout strong small{font-size:12px;color:#a4b9bd}.meter{height:3px;background:#ffffff20;width:100%;margin-top:3px}.meter i{height:100%;display:block;background:#ec8b69;box-shadow:0 0 9px #ed8a68;transition:width .5s}.meter.cyan i{background:#75ddd1;box-shadow:0 0 9px #75ddd1}.mode-pill{display:inline-flex;align-items:center;gap:8px;margin-top:8px;padding:8px 10px;border:1px solid #ffffff23;background:#06121ac4;font:9px 'DM Mono',monospace;letter-spacing:.12em;color:#c4d5d7}.mode-dot{width:6px;height:6px;border-radius:50%;background:#edb887;box-shadow:0 0 8px #edb887}.objective{position:absolute;z-index:3;left:50%;top:105px;transform:translateX(-50%);width:270px;text-align:center;padding:11px 16px 13px;background:linear-gradient(180deg,#07121ba6,transparent);pointer-events:none}.obj-kicker{display:flex;justify-content:space-between;color:#91aaaF;font:9px 'DM Mono',monospace;letter-spacing:.12em}.obj-kicker span:last-child{color:#74d7ce}.obj-title{font-size:19px;font-weight:600;margin:8px 0 3px}.obj-desc{font-size:11px;color:#a5b8bc;line-height:1.5}.objective-progress{margin-top:11px;text-align:left}.objective-progress>span{font:9px 'DM Mono',monospace;color:#9eb1b5}.progress-track{height:2px;background:#ffffff20;margin-top:5px}.progress-track i{height:100%;width:0;display:block;background:#79ded0;box-shadow:0 0 9px #79ded0;transition:width .4s}.target-marker{z-index:3;position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);display:flex;align-items:center;gap:8px;padding:7px 10px;border:1px solid #9de7de55;background:#07131bbf;color:#b8e4de;font:9px 'DM Mono',monospace;letter-spacing:.08em;white-space:nowrap;transition:opacity .2s}.target-marker b{font-weight:400;color:#f4c597}.target-bracket{font-size:16px}.reticle{position:absolute;z-index:2;left:50%;top:50%;transform:translate(-50%,-50%);width:24px;height:24px;border:1px solid #d5efea4b;border-radius:50%;pointer-events:none}.reticle:before,.reticle:after{content:'';position:absolute;background:#d5efea66}.reticle:before{width:4px;height:1px;left:-3px;top:11px;box-shadow:24px 0 #d5efea66}.reticle:after{width:1px;height:4px;left:11px;top:-3px;box-shadow:0 24px #d5efea66}.reticle i{position:absolute;width:3px;height:3px;left:9.5px;top:9.5px;border-radius:50%;background:#c9e6e2}.action-hint{position:absolute;z-index:4;left:50%;top:calc(50% + 45px);transform:translateX(-50%);display:flex;align-items:center;gap:9px;font:10px 'DM Mono',monospace;letter-spacing:.1em;color:#c8e3dc;opacity:0;transition:opacity .2s}.action-hint.visible{opacity:1}.action-hint kbd{padding:5px 8px;border:1px solid #8ce2d7;background:#0a201f;color:#d9fff6;border-radius:3px}.toast{position:absolute;z-index:4;left:50%;top:61%;transform:translate(-50%,-10px);padding:11px 18px;background:#11302bdb;border:1px solid #6de0bd88;color:#aaf3d9;font:10px 'DM Mono',monospace;letter-spacing:.1em;opacity:0;transition:all .3s;pointer-events:none}.toast.visible{opacity:1;transform:translate(-50%,0)}.warning{position:absolute;z-index:3;top:65px;left:50%;transform:translateX(-50%);color:#ffc18c;font:9px 'DM Mono',monospace;letter-spacing:.11em;opacity:0;transition:opacity .3s}.warning.visible{opacity:1}.nav-bottom{position:absolute;z-index:3;bottom:25px;left:34px;right:34px;display:flex;align-items:flex-end;justify-content:space-between;pointer-events:none}.coordinates b,.velocity b,.tether b{display:block;margin-top:6px;font:11px 'DM Mono',monospace;letter-spacing:.04em;color:#e0eae8}.tether{width:160px}.tether-line{height:2px;background:#ffffff25;margin-top:9px;position:relative}.tether-line i{display:block;width:60%;height:2px;background:#81dcd0;box-shadow:0 0 7px #81dcd0}.tether b{position:absolute;right:0;bottom:-17px;font-size:9px}.velocity{text-align:right}.velocity b{font-size:15px}.velocity small{font-size:9px;color:#9fb4b7}.touch-controls{display:none}.intro,.end-screen{position:absolute;inset:0;z-index:6;display:grid;place-items:center;background:linear-gradient(90deg,rgba(3,8,15,.9) 0%,rgba(4,10,16,.68) 43%,rgba(5,11,18,.05) 100%);transition:opacity .6s,visibility .6s}.intro.hidden,.end-screen.hidden{opacity:0;visibility:hidden;pointer-events:none}.intro-card{position:absolute;left:10%;top:50%;transform:translateY(-46%);width:min(430px,45vw)}.eyebrow{display:flex;align-items:center;gap:9px;color:#9bb2b6;font:9px 'DM Mono',monospace;letter-spacing:.14em}.intro h1,.end-card h2{font-size:clamp(39px,5.1vw,68px);line-height:.98;letter-spacing:-.06em;font-weight:500;margin:24px 0 14px}.intro h1 em,.end-card h2 em{font-family:Georgia,serif;font-weight:400;color:#86d8d0}.intro-card>p,.end-card>p{max-width:380px;color:#afc0c2;font-size:13px;line-height:1.75}.intro-stats{display:flex;gap:25px;margin:27px 0 30px;padding:15px 0;border-top:1px solid #ffffff24;border-bottom:1px solid #ffffff24}.intro-stats div{display:flex;flex-direction:column;gap:7px}.intro-stats span{font:8px 'DM Mono',monospace;letter-spacing:.12em;color:#80979c}.intro-stats b{font:9px 'DM Mono',monospace;letter-spacing:.06em;font-weight:400;color:#d7e3e1}.intro-stats b.hazard{color:#f5b27e}.start-btn{border:0;background:#b1e6d9;color:#09201e;padding:14px 19px;min-width:170px;text-align:left;font-size:11px;font-weight:700;letter-spacing:.1em;cursor:pointer;transition:background .2s,transform .2s}.start-btn:hover{background:#d5fff2;transform:translateY(-2px)}.start-btn span{float:right;font-size:16px;line-height:12px}.controls-copy{margin-top:17px;color:#82989c;font:8px 'DM Mono',monospace;letter-spacing:.05em}.controls-copy b{color:#bacdc9;margin-left:7px}.intro-foot{position:absolute;bottom:24px;left:34px;right:34px;display:flex;justify-content:space-between;color:#81969b;font:8px 'DM Mono',monospace;letter-spacing:.14em}.end-card{padding:35px;background:#07121bd9;border:1px solid #a3e6dc42;backdrop-filter:blur(12px);max-width:450px}.end-card h2{font-size:55px;margin:19px 0}.end-card>p{margin-bottom:25px}.end-screen{background:#02070aaa;backdrop-filter:blur(5px)}
@media(max-width:700px){.topbar{padding:15px 17px}.brand{font-size:10px}.brand small{display:none}.mission-tag{top:58px;font-size:8px}.icon-btn{width:31px;height:31px}.hud-left{left:16px;top:92px;width:120px}.readout{margin-bottom:12px}.readout>span{font-size:7px}.readout strong{font-size:20px}.mode-pill{font-size:8px;padding:6px 8px}.objective{top:89px;width:190px;padding:7px 8px 9px}.obj-kicker{font-size:7px}.obj-title{font-size:15px;margin:5px 0 2px}.obj-desc{font-size:9px}.objective-progress{margin-top:7px}.objective-progress>span{font-size:7px}.warning{top:77px;font-size:8px}.nav-bottom{bottom:15px;left:16px;right:16px}.coordinates>span,.velocity>span,.tether>span{font-size:7px}.coordinates b,.velocity b{font-size:9px}.tether{width:90px}.tether b{font-size:8px}.reticle{width:20px;height:20px}.reticle:before{box-shadow:20px 0 #d5efea66}.reticle:after{box-shadow:0 20px #d5efea66}.reticle i{left:7.5px;top:7.5px}.action-hint{top:calc(50% + 33px);font-size:8px}.target-marker{font-size:8px}.intro{background:linear-gradient(90deg,rgba(3,8,15,.9),rgba(4,10,16,.55))}.intro-card{left:7%;width:86%;top:48%;transform:translateY(-45%)}.intro h1{font-size:clamp(42px,11vw,61px);margin:18px 0 12px}.intro-card>p{font-size:12px;max-width:340px}.intro-stats{gap:14px;margin:20px 0 22px}.intro-stats span{font-size:7px}.intro-stats b{font-size:7px}.controls-copy{max-width:300px;line-height:1.9;font-size:7px}.intro-foot{left:16px;right:16px;bottom:13px;font-size:7px}.touch-controls{display:block;position:absolute;inset:0;z-index:4;pointer-events:none}.joystick{position:absolute;bottom:66px;left:19px;width:116px;height:116px;border:1px solid #d3eeea44;border-radius:50%;background:#08162055;pointer-events:auto;touch-action:none}.joystick:before,.joystick:after{content:'';position:absolute;background:#ffffff13}.joystick:before{width:100%;height:1px;top:50%}.joystick:after{height:100%;width:1px;left:50%}.joy-knob{position:absolute;width:47px;height:47px;left:34px;top:34px;border:1px solid #bce7df99;background:#8fdacb3d;border-radius:50%;z-index:1}.joy-up,.joy-down{position:absolute;left:52px;color:#afccc8;font-size:11px;opacity:.65}.joy-up{top:8px}.joy-down{bottom:7px}.touch-actions{pointer-events:auto;position:absolute;right:17px;bottom:65px;display:flex;flex-direction:column;align-items:flex-end;gap:8px}.touch-btn{background:#07131bbd;border:1px solid #bad6d343;padding:10px 12px;font:8px 'DM Mono',monospace;letter-spacing:.1em;color:#d3e6e1;min-width:69px;touch-action:manipulation}.touch-btn.primary-action{background:#96dbc975;border-color:#a7f2e39c;color:#f3fff9}.look-hint{position:absolute;bottom:38px;left:50%;transform:translateX(-50%);font:7px 'DM Mono',monospace;color:#a2b9ba;letter-spacing:.14em}.end-card{margin:20px;padding:26px}.end-card h2{font-size:47px}}
@media(max-height:500px) and (max-width:900px){.hud-left{top:72px}.objective{top:65px}.topbar{padding-top:10px}.joystick{width:90px;height:90px;bottom:50px}.joy-knob{width:37px;height:37px;left:26px;top:26px}.joy-up,.joy-down{left:40px}.touch-actions{bottom:47px}.intro-card{top:45%;}.intro h1{font-size:40px;margin:12px 0}.intro-card>p{font-size:10px}.intro-stats{margin:12px 0}.intro-foot{bottom:8px}}

import * as THREE from './vendor/three.module.js';

const canvas=document.querySelector('#scene');
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setSize(innerWidth,innerHeight);renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.15;
const scene=new THREE.Scene();scene.background=new THREE.Color(0x050a12);scene.fog=new THREE.FogExp2(0x050a12,.0035);
const camera=new THREE.PerspectiveCamera(63,innerWidth/innerHeight,.1,700);camera.position.set(-5,5,14);
scene.add(new THREE.HemisphereLight(0x789daf,0x101522,1.15));const keyLight=new THREE.DirectionalLight(0xc3e6ee,2.1);keyLight.position.set(-9,12,8);scene.add(keyLight);const fill=new THREE.PointLight(0x4fc9da,55,90);fill.position.set(6,3,-4);scene.add(fill);
const mat=(color,metalness=0,roughness=.7,emissive=0,ei=0)=>new THREE.MeshStandardMaterial({color,metalness,roughness,emissive,emissiveIntensity:ei});
const world=new THREE.Group();scene.add(world);
// Starfield: layered points for a deep, quiet sky.
let starPos=[],starColors=[];for(let i=0;i<2400;i++){const r=THREE.MathUtils.randFloat(85,250),a=Math.random()*Math.PI*2,b=Math.acos(THREE.MathUtils.randFloatSpread(2));starPos.push(r*Math.sin(b)*Math.cos(a),r*Math.cos(b),r*Math.sin(b)*Math.sin(a));const tint=Math.random();starColors.push(.48+tint*.48,.6+tint*.35,.72+tint*.28)}const starGeo=new THREE.BufferGeometry();starGeo.setAttribute('position',new THREE.Float32BufferAttribute(starPos,3));starGeo.setAttribute('color',new THREE.Float32BufferAttribute(starColors,3));const stars=new THREE.Points(starGeo,new THREE.PointsMaterial({size:.8,vertexColors:true,transparent:true,opacity:.9,sizeAttenuation:false}));scene.add(stars);
// Distant dust / debris.
for(let i=0;i<55;i++){const rock=new THREE.Mesh(new THREE.IcosahedronGeometry(THREE.MathUtils.randFloat(.12,.55),0),mat(i%3?0x303743:0x5c5148,.45,.9));rock.position.set(THREE.MathUtils.randFloatSpread(72),THREE.MathUtils.randFloatSpread(36),THREE.MathUtils.randFloat(-80,18));rock.rotation.set(Math.random()*3,Math.random()*3,Math.random()*3);rock.userData.spin=(Math.random()-.5)*.004;world.add(rock)}
// Gravitational lensing landmark: a dark core, glowing accretion rings, bent light.
const blackhole=new THREE.Group();blackhole.position.set(-34,13,-57);world.add(blackhole);
const hole=new THREE.Mesh(new THREE.SphereGeometry(7.5,48,32),new THREE.MeshBasicMaterial({color:0x010207}));blackhole.add(hole);
const diskMat=new THREE.MeshBasicMaterial({color:0xf28c55,transparent:true,opacity:.68,side:THREE.DoubleSide});const disk=new THREE.Mesh(new THREE.TorusGeometry(11,.8,10,120),diskMat);disk.rotation.x=Math.PI/2.5;blackhole.add(disk);
for(let i=0;i<3;i++){const ring=new THREE.Mesh(new THREE.TorusGeometry(8.9+i*.72,.12+i*.045,8,110),new THREE.MeshBasicMaterial({color:i===1?0xffd095:0x9b6aff,transparent:true,opacity:.72-i*.12}));ring.rotation.x=Math.PI/2.5+(i-1)*.025;blackhole.add(ring)}
const halo=new THREE.PointLight(0xb77ce9,170,75);halo.position.set(0,2,0);blackhole.add(halo);
// Quasar: a hot white-blue engine with twin energy jets.
const quasar=new THREE.Group();quasar.position.set(35,9,-42);world.add(quasar);
const core=new THREE.Mesh(new THREE.SphereGeometry(2.1,32,24),new THREE.MeshBasicMaterial({color:0xd9faff}));quasar.add(core);
const qLight=new THREE.PointLight(0x66cfff,260,100);quasar.add(qLight);
const qGlow=new THREE.Mesh(new THREE.SphereGeometry(3.2,28,20),new THREE.MeshBasicMaterial({color:0x27aaff,transparent:true,opacity:.18,side:THREE.BackSide}));quasar.add(qGlow);
const jetMat=new THREE.MeshBasicMaterial({color:0x67d9ff,transparent:true,opacity:.22,side:THREE.DoubleSide});for(const sign of [-1,1]){const jet=new THREE.Mesh(new THREE.CylinderGeometry(.35,3.8,31,24,1,true),jetMat);jet.position.y=sign*17;quasar.add(jet)}
for(let i=0;i<4;i++){const qr=new THREE.Mesh(new THREE.TorusGeometry(3.3+i*.72,.08,6,80),new THREE.MeshBasicMaterial({color:0x88dbff,transparent:true,opacity:.5-i*.08}));qr.rotation.x=Math.PI/2+(i*.12);quasar.add(qr)}
// Rescue ship: purposeful, readable silhouette with cockpit, engine, fins and repair lights.
const ship=new THREE.Group();world.add(ship);ship.position.set(0,0,0);
const hull=mat(0x637581,.72,.34),dark=mat(0x1b2b35,.6,.42),panel=mat(0x30414d,.7,.37),glass=new THREE.MeshPhysicalMaterial({color:0x49b8cc,metalness:.45,roughness:.12,transparent:true,opacity:.72,emissive:0x0b4352,emissiveIntensity:.7}),orange=mat(0xb97751,.45,.45,0x5d2411,.5);
function box(parent,x,y,z,sx,sy,sz,m,r=[0,0,0]){const o=new THREE.Mesh(new THREE.BoxGeometry(sx,sy,sz),m);o.position.set(x,y,z);o.rotation.set(...r);parent.add(o);return o}
function cylinder(parent,x,y,z,rt,rb,h,m,rot=[0,0,0]){const o=new THREE.Mesh(new THREE.CylinderGeometry(rt,rb,h,16),m);o.position.set(x,y,z);o.rotation.set(...rot);parent.add(o);return o}
// Axis is ship length (z), cockpit at +z.
const fus=new THREE.Mesh(new THREE.CapsuleGeometry(1.05,4.6,6,12),hull);fus.rotation.x=Math.PI/2;ship.add(fus);
const nose=new THREE.Mesh(new THREE.ConeGeometry(1.03,2.8,12),hull);nose.rotation.x=-Math.PI/2;nose.position.z=3.45;ship.add(nose);
const cockpit=new THREE.Mesh(new THREE.SphereGeometry(.83,20,16),glass);cockpit.scale.set(1.16,.72,1.15);cockpit.position.set(0,.68,2.3);ship.add(cockpit);
box(ship,0,-.8,0,1.8,.34,4.2,dark);box(ship,0,-.52,-.65,1.58,.22,1.25,panel);
for(const side of [-1,1]){const wing=new THREE.Mesh(new THREE.BoxGeometry(3.6,.24,2.4),hull);wing.position.set(side*2.35,-.18,-.25);wing.rotation.y=side*.09;ship.add(wing);box(ship,side*3.1,-.04,-.15,.85,.11,1.05,orange);box(ship,side*1.35,.04,-2.4,.45,.56,1.4,dark,[0,0,side*.12]);cylinder(ship,side*.95,0,-3.35,.48,.62,1.6,dark,[Math.PI/2,0,0]);const exhaust=new THREE.Mesh(new THREE.CircleGeometry(.38,16),new THREE.MeshBasicMaterial({color:0x68d9f3}));exhaust.position.set(side*.95,0,-4.18);exhaust.rotation.x=Math.PI;ship.add(exhaust)}
for(let i=0;i<5;i++){box(ship,-.65+i*.32,1.04,-.5,.17,.025,1.35,mat(0x8db6bc,.25,.5,0x2a5b67,.5))}
// EVA astronaut. Visor faces +Z; mesh follows flight direction.
const player=new THREE.Group();world.add(player);player.position.set(-4.6,1.25,5.8);
const suit=mat(0xc9d2ce,.18,.55),suitDark=mat(0x293d48,.42,.45),visor=new THREE.MeshPhysicalMaterial({color:0x53aebd,metalness:.75,roughness:.12,emissive:0x0c5961,emissiveIntensity:.8});
const torso=new THREE.Mesh(new THREE.CapsuleGeometry(.43,.68,4,8),suit);torso.position.y=.2;player.add(torso);
const pack=box(player,0,.2,-.53,.65,.82,.39,suitDark);const helmet=new THREE.Mesh(new THREE.SphereGeometry(.36,20,16),suit);helmet.position.set(0,.94,0);player.add(helmet);const visorMesh=new THREE.Mesh(new THREE.SphereGeometry(.285,20,16),visor);visorMesh.scale.set(1,.74,.36);visorMesh.position.set(0,.96,.265);player.add(visorMesh);
for(const s of [-1,1]){const arm=new THREE.Mesh(new THREE.CapsuleGeometry(.14,.55,3,7),suit);arm.position.set(s*.55,.2,0);arm.rotation.z=-s*.18;player.add(arm);const glove=new THREE.Mesh(new THREE.SphereGeometry(.16,10,8),suitDark);glove.position.set(s*.58,-.2,.03);player.add(glove);const leg=new THREE.Mesh(new THREE.CapsuleGeometry(.17,.48,3,7),suitDark);leg.position.set(s*.23,-.65,0);leg.rotation.x=-.08;player.add(leg)}
const lamp=new THREE.PointLight(0x8ef9eb,1.6,5);lamp.position.set(0,.55,.42);player.add(lamp);
// Repairable ship systems, each with a little holographic marker.
const nodes=[];const nodePositions=[new THREE.Vector3(1.38,.75,1.15),new THREE.Vector3(-1.48,-.38,-.55),new THREE.Vector3(.82,.98,-2.05)];
nodePositions.forEach((p,i)=>{const g=new THREE.Group();g.position.copy(p);ship.add(g);const base=new THREE.Mesh(new THREE.BoxGeometry(.78,.68,.12),dark);g.add(base);const face=new THREE.Mesh(new THREE.BoxGeometry(.5,.4,.035),mat(0x512d28,.25,.55,0x9b3c23,.7));face.position.z=.08;g.add(face);for(let n=0;n<3;n++){const line=new THREE.Mesh(new THREE.BoxGeometry(.31,.035,.025),orange);line.position.set(0,.11-n*.11,.11);g.add(line)}const ring=new THREE.Mesh(new THREE.TorusGeometry(.58,.025,5,32),new THREE.MeshBasicMaterial({color:0xffa66f,transparent:true,opacity:.85}));g.add(ring);const dot=new THREE.Mesh(new THREE.SphereGeometry(.08,8,6),new THREE.MeshBasicMaterial({color:0xffa66f}));dot.position.set(.32,.33,.13);g.add(dot);nodes.push({group:g,done:false,index:i,ring,face})});
// Floating ship beacon.
const beacon=new THREE.Group();beacon.position.set(0,4.6,0);ship.add(beacon);const beaconBeam=new THREE.Mesh(new THREE.CylinderGeometry(.025,.025,1.6,6),new THREE.MeshBasicMaterial({color:0x78eee0,transparent:true,opacity:.45}));beaconBeam.position.y=-.8;beacon.add(beaconBeam);const beaconDot=new THREE.Mesh(new THREE.SphereGeometry(.12,12,8),new THREE.MeshBasicMaterial({color:0x9affef}));beacon.add(beaconDot);

