const beaconDot=new THREE.Mesh(new THREE.SphereGeometry(.12,12,8),new THREE.MeshBasicMaterial({color:0x9affef}));beacon.add(beaconDot);

const $=s=>document.querySelector(s);let started=false,mode='eva',oxygen=100,hullValue=62,velocity=new THREE.Vector3(),yaw=0,pitch=.08,repairing=null,repairTime=0,toastTimer=0,elapsed=0,won=false;const keys=new Set();let joy={x:0,y:0},boosting=false,mouseDown=false,lastPointer={x:0,y:0};
